quests[32792] = { id = 32792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leave Nothing Behind!", description = "The Thunderlord clan has become a thorn in my side I will no longer tolerate.\n\nGo east and leave none alive! Burn their supplies! Leave them nothing to cling to.\n\nConverge on the Savage Crag to the east when it is done.", completion = "Hrmph. The burning smell of Thunderlord. This pleases me, {class}.", objectives = "Kill Kur'ak the Binder, burn the Thunderlord Supplies, and destroy the Thunderlord Ballistae.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32793] = { id = 32793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak to Ga'nar" }
quests[32794] = { id = 32794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath of Gronn", description = "The Thunderlord are capturing gronn for the Iron Horde. Show these fools why gronn are NOT pets. \n\nFollow us into Grulloc's Grotto and sunder the chains of the captive gronn. Let the beasts seek to gain their own vengeance against the Thunderlord.\n\nMeet us at Grulloc's Lair beneath the grotto when you are done.", completion = "For many years I hunted all sorts of prey alongside my father. This hunt shall honor his memory as well as avenge his death at the hands of these traitorous, honorless Thunderlords.", objectives = "Release 3 Captive Gronn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32795] = { id = 32795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eldest", description = "There is Hatock, last and eldest son of the Iron Wolf. One of the greatest hunters the Thunderlord have ever fielded.\n\nHe was there when his father murdered my father and left me for dead.\n\nWhen I am done with him he will regret not finishing the job.", completion = "Today is a good day.", objectives = "Help Ga'nar win his vengeance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32796] = { id = 32796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Garrison", description = "My father is avenged. The sons of the Iron Wolf are all slain.\n\nGo to the garrison your people are constructing in the south. There, herald my return to my laggard brother.\n\nThe time has come for the \"chieftain\" to be reminded of what it means to be a Frostwolf.", completion = "Ga'nar is coming. Good. We need his forces if we are to press the advantage.\n\nI can only hope his bloodlust has quelled enough for him to listen to reason.", objectives = "Meet with Durotan in front of your garrison in Frostfire Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32797] = { id = 32797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "END OF PROTOTYPE! [Return to Durotan at Ogre Citadel]", description = "Ah! The weapons of my father, Garad. Too long this beast has coveted them as trophies, memories of slaying our beloved chieftain. I thank you Outsider. Your help today has proven most useful indeed.\n\nNow I must bring these artifacts before my brother. The time has come for he and I to have a proper discussion about leadership.", sourceObjective = "Stay tuned for more thrilling adventures with Durotan, Ga'nar and the Frostwolf Clan!", sourceObjectiveStatus = "unverified-source-field" }
quests[32799] = { id = 32799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Task: Retrieve Scorpar Husk Fragments" }
quests[32800] = { id = 32800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Task: Retrieve Wooly Clefthoof Pelts" }
quests[32801] = { id = 32801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Task: Retrieve Thunderlord Insignias" }
quests[32802] = { id = 32802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Task: Retrieve Warm Frostpear Bulbs" }
quests[32803] = { id = 32803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Thunderlord Cache 01" }
quests[32804] = { id = 32804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Articles of the Fallen", description = "Even when on a mission of vengeance we must remember to uphold the honor that is required of a member of the Frostwolves.\n\nIn the grotto below are the fallen corpses of many good Frostwolf orcs. They must be remembered.\n\nWhile you carry out Ga'nar's task, look for articles of our fallen brethren. Bring these articles to me so that I might pass them to a shaman for final burial as is our tradition.", progress = "Have you found the articles?", completion = "You have shown honor to our clan. This act shall be remembered.", objectives = "Recover 10 Fallen Frostwolf Artifacts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32805] = { id = 32805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Celestial Blessings", description = "I would like to grant you my full array of draconic power, but sadly, it would tear your mortal frame apart. Still, it's not hopeless - I believe I can create a powerful vessel that you can use.\n\nTo craft it, I will need the blessings of the four August Celestials in Pandaria. Travel with me to the four temples and we will speak to each. To be worthy of their gifts, you must defeat one of their challenges.\n\nThey will not be easy - chose the one challenge best suited to your equipment and skills!", completion = "We have the four blessings of the celestials, and you have proven yourself by completing one of their challenges! I knew I saw great potential in you.", objectives = "Travel to the Temple of the White Tiger in Kun-Lai, the Temple of the Red Crane in Krasarang, the Temple of the Jade Serpent in the Jade Forest, and Niuzao Temple in Townlong Steppes to obtain four blessings of the celestials. Complete ONE of their four available challenges.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32806] = { id = 32806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The King and the Council", description = "I am glad you are here, {name}. I have been using my dream brew to experience events around the world, but the more I learn, the more confused I become.\n\nFor instance, King Wrynn has asked the dwarves of Ironforge for more troops, but they do not all support him.\n\nI will tell you more, but I would also like to hear from your experience firsthand...", progress = "It is not my place to make stories. I simply tell them.", completion = "So, King Wrynn and the Dark Iron dwarves saved the city, and the bitterly divided Council of Three Hammers gained a new unity under the Alliance banner. How interesting!\n\nBut what is happening within the Horde?", objectives = "Complete the \"Blood in the Snow\" scenario. You can queue from the Dungeon Finder or use Lorewalker Cho's Dream Brew.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32807] = { id = 32807, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warchief and the Darkness", description = "I see now how the Alliance king leads his people. But what is the Horde warchief up to? Just below us, a swarm of goblins are burrowing into the sacred vale on his orders. What does he hope to find there? We must find out!", progress = "It is not my place to make stories. I simply tell them.", completion = "Whaaaat? The remains of an Old God are buried beneath Pandaria? No wonder the land is so haunted!\n\nThe warchief's pursuit of those dormant powers are fraying apart the very Horde he leads. His vision is narrow, but very, very dangerous. I must inform the Shado-Pan immediately.", objectives = "Complete the \"Dark Heart of Pandaria\" scenario. You can queue from the Dungeon Finder or use Lorewalker Cho's Dream Brew.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32808] = { id = 32808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Field Work", description = "My dream brew can only tell me so much. Its visions are scattered in time and space. But it is clear that a showdown is brewing at the Horde capital of Orgrimmar.\n\nYou should go there, and see these events for yourself!\n\nIn my dream brew I see two brave Alliance spies alone in Durotar. I see \"Amber\" and \"Sully\"...\n\nPerhaps you remember them? I think they need your help!\n\nYou'll find Amber and Sully in Kalimdor, near Skull Rock, at a place called the Dranosh'ar Blockade.", completion = "{name}! I cannot tell you how relieved I am to have some backup!\n\nKing Wrynn himself sent us to gather intel on Garrosh's activities and Orgrimmar's defenses, but... things are looking grim.\n\nWe need your help.", objectives = "Secure passage to Kalimdor from Gleep Chatterswitch at the Shrine of Seven Stars. Then speak with Amber Kearnen, who is scouting Bladefist Bay near Skull Rock in Durotar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32809] = { id = 32809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering Intelligence", description = "Garrosh continues building up his forces in Orgrimmar - this place is like a fortress!\n\nKing Wrynn won't want to risk an assault until we have as much information as possible.\n\nUse Project C4T to navigate through the Blockade. Try to gather as much information as you can. Look for any high priority documents and any weakness we can take advantage of. Keep your ears open and your head down!", progress = "Did you find us anything useful?", completion = "Let's see... the warchief is moving tons of supplies through the Barrens... And what's this about the Darkspear? The trolls are in open rebellion?! Garrosh certainly has his hands full.\n\nI think I know how we can use this intel. It's a crazy idea, but it just might work...", objectives = "Obtain the Kor'kron Supply Lines, Operation: Darkspear Destruction, Kor'kron Command Posts, and free the prisoner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32810] = { id = 32810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Darkspear Rebellion", description = "The trolls are in open rebellion. This could work to our advantage! If they open up a second front, Garrosh cannot possibly defend the city from us both.\n\nI have a very risky assignment for you. I need you to be the Alliance representative, and open up talks with Vol'jin of the Darkspear tribe.\n\nTry finding the troll prisoner that we freed from Kor'kron clutches. Zen'tabra, wasn't it?\n\nIt may be our only chance to bring Garrosh to his knees...", completion = "<Zen'tabra narrows her eyes at you.>\n\nWhy de Alliance seek de Darkspear? We fightin' de \"Warchief,\" sure, but dat don't mean we friends. I never trust de Alliance, an' I ain't 'bout ta start now.\n\nStill, dat funny mechanical cat ya have saved me life... so I give you dis. I let ya speak wit' Vol'jin.\n\nLet him decide if ya words be venom or honey.\n\nDon't be tryin' nothin', {class}. Ya lift a finger against Vol'jin, ya life be forfeit.", objectives = "Speak with Zen'tabra at Razor Hill in Durotar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32811] = { id = 32811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battlefield: Barrens", description = "Ya want we work together on dis, ya gotta earn me trust.\n\nIn Northern Barrens, de Kor'kron be massin' for war. Hellscream's goons be stockpilin' lumber, oil, stone, an' meat. Supplies de Darkspear want ta use against' 'im.\n\nGo to de Barrens. Kill de Kor'kron. Bring me dem supplies! Fight dem wherever dey spring up, escort supply caravans, group up ta take down de dangerous ones. Whatever ya gotta do.\n\nProve ta me da Alliance wants dis! I be watchin'.", progress = "I need dem Kor'kron supplies ta fuel de Darkspear Rebellion.", completion = "<Vol'jin motions to his guards to allow you to come forward and speak.>\n\nDe Barrens be splattered wit' blood, {race}. Ya done right by me.\n\nTell de Alliance ta rally its fleet. When de time comes, de Darkspear an' de other rebels will try ta hold de harbor for ya. Hellscream made too many enemies ta fight 'em all off at once, hah!\n\n\n\nYa have me thanks, {race}. Dis rebellion only gonna get so far wit'out ya.", objectives = "Collect 15 Kor'kron Lumber, 15 Kor'kron Oil, 15 Kor'kron Meat, and 15 Kor'kron Stone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32812] = { id = 32812, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Darkspear Rebellion", description = "My dream brew can only tell me so much. Its visions are scattered in time and space. But it is clear that a showdown is brewing amongst the Horde.\n\nIn my dream brew I see that the troll Vol'jin of the Darkspear has already travelled to Durotar to defend his people. He is accompanied by Chen Stormstout, the brewmaster from the Wandering Isle.\n\nIf I have learned anything about Chen, it won't be long before he brews up some trouble... You should hurry!", completion = "<Ki'ta Arrowtusk beckons you over.>\n\nI been waiting for ya, hero. Dis be a time of reckoning.", objectives = "Travel to Durotar and speak with Ki'ta Arrowtusk in Sen'jin Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32813] = { id = 32813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle of Sen'jin Village", description = "<Distant war drums sound.>\n\n{class}, you always be in de right place at de right time. Hellscream be makin' a move against his own people.\n\nHe gonna find out what happens when you cross de Darkspear. Come! Fight wit' us! Show him de spirit of de real Horde!", completion = "De \"Warchief\" thought we'd scatter once he sent in de Kor'kron. Hah. He shoulda sent ev'ryting he got.\n\nTime ta make 'im pay!", objectives = "Defend Sen'jin Village from the Kor'kron assault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32814] = { id = 32814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle of Razor Hill", description = "Now, we hit back! We don't give Hellscream no time to regroup. We ride north. We slit every Kor'kron throat we see.\n\nIf we take Razor Hill, we control all de roads in Durotar.\n\nCome! Ride wit' me!", completion = "Razor Hill. We did it, {name}! Look to de north - you can almost see Orgrimmar from here.\n\nHellscream gonna figure out who did dis. Hah hah. He gonna be one angry orc.\n\nNext stop is de capital. We gonna need a lot more help. An' more supplies...", objectives = "Free 6 Captives and defeat Kor'kron leaders to capture Razor Hill for the Darkspear revolutionaries.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32815] = { id = 32815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Old Seer", description = "I can help you collect the pieces a story, but it is up to you tie them together. And I may know just where you could do such a thing.\n\nI have heard tales of an elderly scholar named Seer Hao Pham Roo. He is something of an... expert on Pandaria's history, and may be able to shed light on Pandaria's current turmoil.\n\nSeek him out, {name}. Last I heard, he was planning to retrace the emperor's steps by scaling Mount Neverest, in Kun-Lai.", completion = "<Huff> Oh, hello- <puff> hello there, young man.\n\nQuite the squall we're having up here today, isn't it?", objectives = "Locate Seer Hao Pham Roo on the slopes of Mount Neverest in Kun-Lai Summit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32816] = { id = 32816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of the Last Emperor", description = "In his time of uncertainty, the last emperor walked a lonely path up this mountain, until he had at last found his answers.\n\nI am here to walk the same path, and it seems you have questions of your own to be answered. Perhaps you will join me, and we can both be satisfied?\n\nOh, but I am getting old, and this blizzard is proving too much for my bones. Could you climb ahead and anchor this rope? I can hoist myself along from there.\n\nTogether we shall walk the path of the last emperor.", completion = "We made it, {class}! Thank you so much. Please, help yourself to some of my old knick-knacks.\n\nBut... I am afraid I have not been completely honest with you...", objectives = "Attach the climbing rope to each Rope Anchor along the path to help Seer Hao Pham Roo reach Seeker's Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32817] = { id = 32817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Complete \"Loyalty\" Scenario" }
quests[32818] = { id = 32818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Complete \"The Dark Heart of Pandaria\" Scenario" }
quests[32819] = { id = 32819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battlefield: Barrens", description = "Ta take down de warchief, I be needin' an army an' supplies. I got me an army. No shortage of hate for what Hellscream done to de Horde. But supplies! Lumber, stone, meat, oil. Dis be what we need.\n\nHellscream's Kor'kron be stockpilin' supplies in Northern Barrens, to de west. Kill de Kor'kron! Fight dem wherever dey spring up. Help our tauren bruddahs by escortin' their caravans, an' group up to take down Kor'kron leaders. Whatever it takes. Get me dem supplies!", progress = "Da Horde be splinterin' under Hellscream's leadership.", completion = "<Sen'jin is buzzing with activity. Vol'jin motions for you to approach, a dark sadistic grin spreading across his tired face.>\n\nYa done good, {name}. Blood in de Barrens. Hellscream got to be feelin' that.\n\nNo doubt he gonna come for us, but we gonna be ready...", objectives = "Collect 15 Kor'kron Lumber, 15 Kor'kron Oil, 15 Kor'kron Meat, and 15 Kor'kron Stone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32825] = { id = 32825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Re-Use Me", objectives = "Kill 10 Kirin Tor units or players on the Isle of Thunder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32826] = { id = 32826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Re-Use Me", objectives = "Plant a Tactical Mana Bomb on a Sunreaver ship, the Scrying Crystals, and on the most inland bridge of Dawnseeker Promontory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32827] = { id = 32827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Re-Use Me", description = "Even the strongest defense can still have a weakness, {class}. We just need to find the weakness in the Sunreaver's defense and then exploit it as much as possible.\n\nScouts have reported the use of perimeter wards around Dawnseeker Promontory. They're powerful, but not deadly.\n\nDisabling them would allow us to keep closer watch on their activities.", objectives = "Destroy 6 Sunreaver Perimeter Wards around Dawnseeker Promontory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32832] = { id = 32832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taran Zhu and Dezco Scene" }
quests[32836] = { id = 32836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Knockoff Grumplefloot", description = "The \"grumplefloot\" has been hastily carved out of a tree root, with holes unevenly spaced along its length.\n\nA close inspection of its backside, however, reveals words carved into the wood:\n\nRETURN TO BRAWLER'S GUILD", progress = "What's that you have there, {class}?", completion = "Ah, you've found one of my treasures. Well done, adventurer.\n\nIn return, I will allow you to purchase one of my rare challenge cards.", objectives = "Return the Knockoff Grumplefloot to someone within your faction's Brawler's Guild.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32837] = { id = 32837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grandpa Grumplefloot", description = "The challenge card I have for you today belongs to a grummle by the adorable name of Grandpa Grumplefloot. While the grummles aren't particularly well-known for their combat skills, they are remarkably lucky little creatures.\n\nPerhaps it's their... what do they call them... their luckydos?", completion = "Great fighting out there! Even if he was just a little guy.\n\nYou've earned every bit of this.", objectives = "Defeat Grandpa Grumplefloot by purchasing his challenge card and challenging him in the Brawler's Guild.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32838] = { id = 32838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tale of Romance and Chivalry", description = "A small book, written for children. It's well-bound and in fairly good condition.\n\nOn the back cover of the book, near the spine, you find a few words written in flowing script:\n\nRETURN TO BRAWLER'S GUILD", progress = "My, my. What's this you've brought me?", completion = "Ah, you've found one of my treasures. Well done, adventurer.\n\nIn return, I will allow you to purchase one of my rare challenge cards.", objectives = "Return The Bear and the Lady Fair to someone within your faction's Brawler's Guild.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32839] = { id = 32839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bear and the Lady Fair", description = "The challenge card you've earned belongs to an unusual pair of characters. I'm not quite sure any further description would do them justice.\n\nMaybe you should just purchase the challenge card and see for yourself.", completion = "You sailed through the air so... so... majestically! Well done!", objectives = "Defeat the Bear and the Lady Fair by purchasing their challenge card and challenging them in the Brawler's Guild.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32840] = { id = 32840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boom Boom's Fuse", description = "Amidst the gibbets of hozen meat and fur flying aimlessly around Kota Kon's sphere of destruction, you seem to have grabbed hold of a small fuse.\n\nThe fuse is created entirely from woven, matted hozen tail hair. It has a strong smell.\n\nNear one of the ends of the fuse, however, is a small paper tag, embossed with the words:\n\nRETURN TO BRAWLER'S GUILD", progress = "What's that scent I detect?", completion = "Ah, you've found one of my treasures. Well done, adventurer.\n\nIn return, I will allow you to purchase one of my rare challenge cards.", objectives = "Return Boom Boom's Fuse to someone within your faction's Brawler's Guild.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32841] = { id = 32841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master Boom Boom", description = "You have earned a card belonging to a bomb-throwing hozen named Master Boom Boom.\n\nWhile hozen are naturally attracted to the destructive power of explosives, they seldom learn how to use them properly without blowing themselves up in the process. Master Boom Boom is the exception.\n\nGood luck!", completion = "I'm not sure how to feel. I wanted you to win, but then again... I also kinda wanted to see you explode.\n\nNo hard feelings! I just like seeing explosions.", objectives = "Defeat Master Boom Boom by purchasing his challenge card and challenging him in the Brawler's Guild.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32842] = { id = 32842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teeth Like Swords", description = "The tooth comes to a singular edge, almost as if it were sharpened by stone. It clearly belonged to a ferocious beast.\n\nHandling it gingerly, you notice a few tiny words, expertly carved into the enamel:\n\nRETURN TO BRAWLER'S GUILD", progress = "You have something for me - I can see it in your eyes. What is it, {class}?", completion = "Ah, you've found one of my treasures. Well done, adventurer.\n\nIn return, I will allow you to purchase one of my rare challenge cards.", objectives = "Return the Impeccably Sharp Tooth to someone within your faction's Brawler's Guild.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32843] = { id = 32843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Razorgrin", description = "The challenge card you've earned today belongs to one of the most deadly creatures in the South Seas: Razorgrin. One bite from those teeth of his, and you're nothing but an unrecognizable pile of skin, blood, and entrails.\n\nHave fun!", completion = "Congratulations!\n\nAlso, how embarrassing would it have been if you got eaten by a beached shark?", objectives = "Defeat Razorgrin by purchasing his challenge card and challenging him in the Brawler's Guild.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32844] = { id = 32844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secret of the Ooze", description = "The contents of the vial swirl and froth violently, causing the vessel to tremble in your hand. As you look into the container, you think you catch a fleeting image of a living, angry face.\n\nThe vial's stopper fits snugly. Around its edge, some small words have been carved with an expert hand:\n\nRETURN TO BRAWLER'S GUILD", progress = "Greetings, {class}.", completion = "Ah, you've found one of my treasures. Well done, adventurer.\n\nIn return, I will allow you to purchase one of my rare challenge cards.", objectives = "Return the Vial of Reddish Ooze to someone within your faction's Brawler's Guild.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32845] = { id = 32845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Splat", description = "You may already be familiar with Blat, one of our Rank 2 challengers here in the Brawler's Guild. The challenge card you've earned belongs to Splat, its older, nastier sister.\n\nTry not to get yourself killed, {name}. And if you do, at least make it entertaining for the rest of us!", completion = "You left quite a mess behind you, but you did it. Well done, {race}!", objectives = "Defeat Splat by purchasing her challenge card and challenging her in the Brawler's Guild.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32846] = { id = 32846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Modified Chomping Apparatus", description = "You might not have recognized this as a modified chomping apparatus if it didn't have the words \"modified chomping apparatus\" messily painted onto it.\n\nRight beneath the sloppy label, you see a smaller message, written much more neatly in bright red ink:\n\nRETURN TO BRAWLER'S GUILD", progress = "Can I help you with something?", completion = "Ah, you've found one of my treasures. Well done, adventurer.\n\nIn return, I will allow you to purchase one of my rare challenge cards.", objectives = "Return the Modified Chomping Apparatus to someone within your faction's Brawler's Guild.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32847] = { id = 32847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mecha-Bruce", description = "Everybody knows Bruce. Everybody loves Bruce! And eventually, everybody kills Bruce.\n\nAn orcish hunter with a knack for engineering thought that this was a shame, so he's found his own crocolisk and geared him up a bit.\n\nThe challenge card you've earned grants you the right to fight Mecha-Bruce. It's bound to be a bloodbath. The question is... will you be the chomper, or the chompee?", completion = "Aww... poor Mecha-Bruce.\n\nI'll give you your reward. But I don't have to be happy about it.", objectives = "Defeat Mecha-Bruce by purchasing his challenge card and challenging him in the Brawler's Guild.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32848] = { id = 32848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frost-Tipped Eggshell", description = "A piece of an eggshell, presumably penguin. Its edges are covered with rime, and based on its curvature, this egg was quite large when it was intact.\n\nStrangely, the inside of the eggshell has a message written on it, in jade-green ink:\n\nRETURN TO BRAWLER'S GUILD", progress = "You have the look of a messenger about you. What do you have for me, {race}?", completion = "Ah, you've found one of my treasures. Well done, adventurer.\n\nIn return, I will allow you to purchase one of my rare challenge cards.", objectives = "Return the Frost-Tipped Eggshell to someone within your faction's Brawler's Guild.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32849] = { id = 32849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dippy and Doopy", description = "Brawler's Guild vets will remember Dippy, the penguin. Dippy's not the most accomplished challenger in the Brawler's Guild, but he's no pushover, either!\n\nActually, come to think of it, he IS kind of a pushover...\n\nAnyway! The card you've earned gives you the right to challenge Dippy alongside his older, huger brother, Doopy. They may both be pushovers, but that doesn't mean that one or both of them won't eventually murder you.", completion = "I never thought I'd say this, but successfully beating up a couple penguins is the sign of a true, tried-and-tested brawler. You've earned your reward.", objectives = "Defeat Dippy & Doopy by purchasing their challenge card and challenging them in the Brawler's Guild.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32850] = { id = 32850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Year's Model", description = "The robot is in bad shape. It was built with several sockets which, like the Blingtron 4000, presumably once carried gems, but are now empty.\n\nThe robot's otherwise dust-covered posterior region contains a small, shiny metal plaque, embossed with the words:\n\nRETURN TO BRAWLER'S GUILD", progress = "What's that you have there, {class}?", completion = "Ah, you've found one of my treasures. Well done, adventurer.\n\nIn return, I will allow you to purchase one of my rare challenge cards.", objectives = "Return the Dusty Old Robot to someone within your faction's Brawler's Guild.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32851] = { id = 32851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blingtron 3000", description = "The Blingtron line didn't really pick up until the 4000 series hit the vendor shelves. Few remember the Blingtron 3000, but it was a real engineering marvel in its own right!\n\nThe challenge card you've unlocked gives you the ability to fight Blingtron 3000 right here, in the Brawler's Guild.\n\nLucky you!", completion = "You've got a real knack for beating up robots, {name}.", objectives = "Defeat Blingtron 3000 by purchasing his challenge card and challenging him in the Brawler's Guild.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32852] = { id = 32852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Digmaster's Earthblade", description = "An entirely ordinary-looking shovel. The handle is carved with an ornate script: \"The Digmaster's Earthblade\".\n\nOn the flipside of the handle, however, is a smaller label, written in simpler text:\n\nRETURN TO BRAWLER'S GUILD", progress = "What are you carrying, {class}? Something of mine?", completion = "Ah, you've found one of my treasures. Well done, adventurer.\n\nIn return, I will allow you to purchase one of my rare challenge cards.", objectives = "Return the Digmaster's Earthblade to someone within your faction's Brawler's Guild.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32853] = { id = 32853, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mingus Diggs", description = "You've earned the right to challenge Mingus Diggs, the archaeologist!\n\nMingus isn't that tough, from what I hear... but the people in charge let him bring some of his excavated treasures with him into the brawling ring. Those are what you want to watch out for.\n\nCome buy his card when you're ready!", completion = "You ran around that arena so quickly, I got dizzy for a moment.\n\nWell done!", objectives = "Defeat Mingus Diggs by purchasing his challenge card and challenging him in the Brawler's Guild.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32854] = { id = 32854, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Well-Worn Blindfold", description = "A piece of cloth, shaped for a human-sized head. The cloth is unadorned and simple, except for a small tag on the end, which reads:\n\nRETURN TO BRAWLER'S GUILD", progress = "You carry something of mine, I believe.", completion = "Ah, you've found one of my treasures. Well done, adventurer.\n\nIn return, I will allow you to purchase one of my rare challenge cards.", objectives = "Return the Well-Worn Blindfold to someone within your faction's Brawler's Guild.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32855] = { id = 32855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blind Hero", description = "The challenge card you've earned allows you to fight the Blind Hero, a mysterious warrior from a bygone age. Nobody surpasses his skill with a blade. Nobody.\n\nLuckily, he can't see anything. Have fun!", completion = "I would normally shame someone for fighting a blind person, but in this case, I have to commend you.\n\nBrilliant brawling, {name}!", objectives = "Defeat the Blind Hero by purchasing his challenge card and challenging him in the Brawler's Guild.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32856] = { id = 32856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paper-Covered Rock", description = "It's a strange combination of items. The paper envelops the rock completely, dwarfing it like a smothering blanket of wood pulp. Compared to the paper, the rock is barely a pebble.\n\nWhen held up to the light, the paper reveals a distinct watermark, along with the text:\n\nRETURN TO BRAWLER'S GUILD", progress = "Good day, {race}. Have you brought something for me?", completion = "Ah, you've found one of my treasures. Well done, adventurer.\n\nIn return, I will allow you to purchase one of my rare challenge cards.", objectives = "Return the Paper-Covered Rock to someone within your faction's Brawler's Guild.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32857] = { id = 32857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ro-Shambo", description = "The challenge card you have unlocked will allow you to fight Ro-Shambo, an esoteric creature from parts unknown.\n\nWatch out. I hear it's got a few tricks up its sleeve.", completion = "You did well! Even if you did get a little lucky...", objectives = "Defeat Ro-Shambo by purchasing her challenge card and challenging her in the Brawler's Guild.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32858] = { id = 32858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raptorhide Boxing Gloves", description = "The gloves are stitched together roughly, and by the smell of it, they've been treated with crawler mucus. Nevertheless, they appear sturdy and functional.\n\nSomewhat unsurprisingly, the inner seam bears the following words:\n\nRETURN TO BRAWLER'S GUILD", progress = "What's that you have there, {class}?", completion = "Ah, you've found one of my treasures. Well done, adventurer.\n\nIn return, I will allow you to purchase one of my rare challenge cards.", objectives = "Return the Raptorhide Boxing Gloves to someone within your faction's Brawler's Guild.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32859] = { id = 32859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ty'thar", description = "You've earned the right to purchase a challenge card, and that card belongs to a troll named Ty'thar.\n\nTy'thar has a very distinct fighting style, and as part of his agreement with the Brawler's Guild, you have to follow his rules:\n\n - Face-to-face fist fighting. No running around.\n\n - Three knockdowns wins the fight.\n\nGood luck!", completion = "Look at you! You went into that arena and beat Ty'thar at his own game.\n\nHere. You deserve this.", objectives = "Defeat Ty'thar by purchasing his challenge card and challenging him in the Brawler's Guild.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32860] = { id = 32860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle of Razor Hill Tracking Quest" }
quests[32861] = { id = 32861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cloak of Virtue", description = "We have what we need. I can create an item that will harness the power of the celestials and, with a little work, may also be able to contain some of my own.\n\nMeet me atop Mason's Folly, east of the Tavern in the Mists in the Veiled Stair, where we've met before. You will be delighted with the results!", completion = "I can custom-tailor the cloak to your preferred abilities. Choose wisely!\n\nThe cloak contains only a fraction of its potential power. I'm already hatching a plan to augment it...", objectives = "Travel to Mason's Folly in the Veiled Stair and speak with Wrathion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32862] = { id = 32862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battlefield: Barrens", description = "Our work be far from finished, {name}. De flames of change burn, but dey can still be snuffed out.\n\nBring me more Kor'kron war supplies, and I'll reward ya well.", progress = "How go the Barrens, {class}?", completion = "<Ki'ta Arrowtusk chuckles to himself.> I see you made a whole lotta Kor'kron heads roll for dese supplies.\n\nWell mon, Vol'jin was right to commend you. Dese supplies will be lastin' us an entire week.", objectives = "[Weekly Quest] Collect 150 Kor'kron Lumber, 150 Kor'kron Oil, 150 Kor'kron Meat, and 150 Kor'kron Stone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32863] = { id = 32863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What We've Been Training For", description = "Are you ready to put your pets to the test? The battle pet arena is no place for low-level rabbits, you'd better have a rocketbot in your pocket and be ready for action. If you've got three fully-experienced pets, find battles against trainers of similar skill and show the world what you've got. You can find the instructions in your Pet Journal.", progress = "Well, you're back, did your pets make it out in one piece?", completion = "I've heard stories about some of your matches circulating around, apparently they were quite a sight to behold! I think you've earned this reward. Congratulations, trainer, and keep up the good work.", objectives = "Defeat 10 players through Find Battle with a team of level 25 pets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32864] = { id = 32864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering Intelligence - Riko Tracking" }
quests[32865] = { id = 32865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering Intelligence - Nazgrim Tracking" }
quests[32866] = { id = 32866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering Intelligence - Zaela Tracking" }
quests[32867] = { id = 32867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vol'jin of the Darkspear", description = "Welcome ta Sen'jin Village, mon. I know you traveled far ta see Vol'jin, leader a' da Darkspear.\n\nBut I must ask ya ta wait a little longer. Let us speak.", completion = "<Vol'jin nods at you.>\n\n{class}. Looks like ya just chose a side.\n\nI hope ya ready ta fight.", objectives = "Listen to Ki'ta Arrowtusk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32868] = { id = 32868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beasts of Fable Book II", description = "The stories of Lucky Yi, Greyhoof, and Skitterer Xi'a will exist in this land, always. Do you wish to meet them in battle once more?", progress = "Do you return victorious?", completion = "I bow to you who continues to walk in the footfalls of the great Pandaren fables.", objectives = "Defeat Lucky Yi, Greyhoof, and Skitterer Xi'a.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32869] = { id = 32869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beasts of Fable Book III", description = "The stories of No-No, Ti'un the Wanderer, and Gorespine will exist in this land, always. Do you wish to meet them in battle once more?", progress = "Do you return victorious?", completion = "I bow to you who continues to walk in the footfalls of the great Pandaren fables.", objectives = "Defeat No-No, Ti'un the Wanderer, and Gorespine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32870] = { id = 32870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preparing to Strike", description = "Events are in motion, {name}. We have one final task to complete before we are ready to move into the final act of my plan.\n\nMy agents tell me that King Wrynn has reassembled a naval fleet after his losses at Theramore, and Vol'jin is marching north across Durotar in open rebellion against the warchief.\n\nSpeak with me again as soon as they are ready to converge on the gates. We will bring this war to a glorious conclusion!", completion = "Are you ready for your next adventure, {class}?\n\nOur campaign is nearing its conclusion...", objectives = "Return to Wrathion at the Tavern in the Mists in the Veiled Stair.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32871] = { id = 32871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vol'jin of the Darkspear", description = "I take ya to Vol'jin.", completion = "<The troll does not have a strong grasp of the common tongue, and his throat is still bandaged from a knife wound. But the meaning of his words is clear.>\n\nWhat de Alliance want wit' ol' Vol'jin, hmm? Zen'tabra says we got a common enemy. That don't make us friends.\n\nBut... Maybe we can work together dis once. You want to strangle de Warchief, hm? Shut 'im out?\n\n<Vol'jin smiles disarmingly, his grin slow and savage.>", objectives = "Accompany Zen'tabra to Vol'jin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32872] = { id = 32872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battlefield: Barrens", description = "Our work be far from finished, {race}. If ya willin' ta put ya neck on the line for the Darkspear once more, I'll be sure ta see ya get a proper reward.", progress = "How go tha Barrens, {race}?", completion = "<Ki'ta Arrowtusk chuckles to himself.> I see you made a whole lotta Kor'kron heads roll for dese supplies.\n\nWell mon, Vol'jin was right to commend you. Dese supplies will be lastin' us an entire week.", objectives = "[Weekly Quest] Collect 150 Kor'kron Lumber, 150 Kor'kron Oil, 150 Kor'kron Meat, and 150 Kor'kron Stone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
