quests[32892] = { id = 32892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War is Coming", description = "As you enter the vale, you see a rotund pandaren trying to flag you down from the balcony above Mogu'shan Palace. It looks like Lorewalker Cho is trying to get your attention. You should investigate!", completion = "Ah! Welcome my friend. I am very glad that I was able to get your attention. Great deeds are at work that require a hero such as yourself.", objectives = "Speak with Lorewalker Cho.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32893] = { id = 32893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Mists - Scenario - Heroic Random - 1st Bonus" }
quests[32894] = { id = 32894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Mists - Scenario - Heroic Random - Nth Bonus" }
quests[32895] = { id = 32895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Road to War", description = "Hey! I just received word from our agents in Durotar.\n\nThe Darkspear Rebellion needs your help.\n\nI hear you've already got an in with the trolls. Why don't you zip over to Durotar and see what's happening?", completion = "It be good to see dat some Alliance have a sense of loyalty.", objectives = "Speak to Ki'ta Arrowtusk at Razor Hill in Durotar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32896] = { id = 32896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Road to War", description = "I have received word from Baine. The Darkspear Rebellion needs your help.\n\nGo to Razor Hill and seek out Ki'ta Arrowtusk.\n\nBreathe word of this to no one!", completion = "Ah, it be good to see your face again, {name}.", objectives = "Speak to Ki'ta Arrowtusk at Razor Hill in Durotar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32897] = { id = 32897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Mists - Scenario - Heroic Daily - 1st/Nth" }
