quests[32899] = { id = 32899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daily Scenario Random (Nth) (Mists)" }
quests[32900] = { id = 32900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroic Deeds", description = "My mind is spinning with boredom - I never get to leave this place!\n\nYou look like you've seen some adventures.  If you can bring me a truly heroic story, I've got something special I'm sure you'll be interested in.", progress = "Anything to tell me, {name}?", completion = "Congratulations, {name}, you did it!  Before I forget, here's the special surprise I promised -- I hope you like it.\n\nNow tell me all about the adventure.  Did you face certain death?  Meet any friends?  I wish I had more friends like you.", objectives = "Complete any scenario on Heroic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32901] = { id = 32901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroic Deeds", description = "My mind is spinning with boredom - I never get to leave this place!\n\nYou look like you've seen some adventures.  If you can bring me a truly heroic story, I've got something special I'm sure you'll be interested in.", progress = "Anything to tell me, {name}?", completion = "Congratulations, {name}, you did it!  Before I forget, here's the special surprise I promised -- I hope you like it.\n\nNow tell me all about the adventure.  Did you face certain death?  Meet any friends?  I wish I had more friends like you.", objectives = "Complete any scenario on Heroic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32910] = { id = 32910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "reuse me", description = "There's more you must do. \n\nKill Itoka, master of the forge, and find a codex fragment from Fleshcrafter Hoku, gatekeeper of the Thunder King.", objectives = "Kill the Master of the Forge and Collect a Codex Fragment from the Mogu Gatekeeper in the Isle of Thunder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
