quests[32929] = { id = 32929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Rely on Numbers", description = "Thunderlord spend their days training to hunt as a team, but as individuals they are weak. Their only strength is in numbers.\n\nSo... to win, we must cull their numbers.\n\nAs we move up through the Daggermaw Ravine, slay any Thunderlord who stand in your way, and their clan will be made the weaker for it.", progress = "My axe bears the blood of a dozen Thunderlord. How many have you slain this day?", completion = "A fine headcount, commander.", objectives = "Slay 15 Thunderlord at Daggermaw Ravine in Frostfire Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
