quests[32942] = { id = 32942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Sunreaver Onslaught I", description = "<Yoon keeps the details of this order short, but detailed.>\n\nAnother request has come through for the Horde. The Sunreaver Onslaught, located out on the Isle of Thunder, has requested a bushel of scallions.\n\nThough this Horde and Alliance conflict still gets my fur in a bristle, I won't turn away a hungry stomach.", objectives = "Plant 8 Scallion Seeds on Sunsong Ranch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32943] = { id = 32943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Sunreaver Onslaught II", description = "Once your scallions are ready to be picked, you'll need only to package them for pick-up.\n\nJust think; your scallions will feed so many hungry soldiers on the front lines!", progress = "The crate sits empty awaiting your crops.", completion = "Throw the scallions into the crate! A Sunreaver Onslaught representative will be along shortly for pick-up.", objectives = "Harvest 8 Ripe Scallion plants and provide 40 Scallions for the Sunreaver Onslaught.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32944] = { id = 32944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Kirin Tor Offensive I", description = "<Yoon keeps the details of this order short, but detailed.>\n\nAnother request has come through for the Alliance. The Kirin Tor Offensive, located out on the Isle of Thunder, has requested a bushel of juicycrunch carrots.\n\nThough this Horde and Alliance conflict still gets my fur in a bristle, I won't turn away a hungry stomach.", objectives = "Plant 8 Juicycrunch Carrot Seeds on Sunsong Ranch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32945] = { id = 32945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Kirin Tor Offensive II", description = "Once your juicycrunch carrots are ready to be picked, you'll need only to package them for pick-up.\n\nJust think; your juicycrunch carrots will feed so many hungry soldiers on the front lines!", progress = "The crate sits empty awaiting your crops.", completion = "Throw the juicycrunch carrots into the crate! A Kirin Tor Offensive representative will be along shortly for pick-up.", objectives = "Harvest 8 Ripe Juicycrunch Carrot plants and provide 40 Juicycrunch Carrots for the Kirin Tor Offensive.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
