quests[32973] = { id = 32973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avatar of Flame Kill Tracking Quest" }
quests[32974] = { id = 32974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rolo's Riddle", description = "<The leather vellum is very old. Stained by age, it bears the following letters:>\n\nOn the isle of time are tall men four\nRound and strong and nothing more\nOf these brothers the shortest be\nWhere the trail leads to me.", completion = "<The dirt here looks overturned. Perhaps something is buried beneath.>", objectives = "Solve the riddle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32975] = { id = 32975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rolo's Riddle", description = "<Another dirty scrap of parchment is buried beneath the soil.>\n\nSomewhere hope stands, wings held forth\nFrom its feet turn to the north\nPass beyond an ancient gate\nBehind a stone pair, I await.", completion = "<Another pile of dirt! Could there be something buried here?>", objectives = "Solve the riddle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32976] = { id = 32976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rolo's Riddle", description = "The final step, my treasure calls\nAbove the place where water falls\nBeneath the shade on vantage high\nNo path to walk but air and sky.", completion = "<The ancient chest has not been disturbed for a long time.>", objectives = "Solve the riddle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32979] = { id = 32979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Campaign: Farseer's Rock", completion = "You again? Not eaten by ogres or killed by Thunderlords yet? Ha!", objectives = "Find Draka and Drek'Thar at Farseer's Rock in Frostfire Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32980] = { id = 32980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eaters of the Elements", description = "Drek'Thar has already begun his ritual, and it is powerful enough to draw the attention of the local goren. Those beasts are drawn to elemental magic like flies to a corpse.\n\nI will have my hands full soon enough. Help us if you like but Drek'Thar must be allowed to finish his ritual.", completion = "I came seeking aid from the elements. I see now that we are the ones who must aid them.\n\nCome, {name}, witness what I have witnessed.", objectives = "Defend Drek'Thar as he performs his ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32981] = { id = 32981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Only the Winner", description = "I am Gronnstalker Rokash, and I only serve the winning side.\n\nI have heard of some of your deeds, commander, and seen the corpses left in the wake of you and your forces.\n\nI have grown tired of my current clan. They are soft, weak, and losing.\n\nI offer you this challenge: enter Colossal's Fall to the north and slay Sky-Singer Strag. Claim her totem as a trophy and I will hail you as my new chieftain.", progress = "Strag always was a coward. She would hide behind her magic and position as a speaker for the dead.", completion = "Strag was the puppet of the Iron Wolf. She would do nothing unless ordered to by him.\n\nThis made us weak, changing us from a force to be feared to a target.\n\nIf this is what the Thunderlord have become then I will have no part of them.", objectives = "Collect Sky-Singer Strag's Totem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32982] = { id = 32982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scavengers of Flame", description = "I sense another child of the fury being consumed by the vile goren in a nearby nest.\n\nSearch the caves east of here for any signs of a goren nest. I suspect there will be quite alot of steam given the cold.\n\nI will try to locate the next child of the fury in your absence.", objectives = "Rescue the Child of Fury at the Forge Gates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32983] = { id = 32983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the Shadow of Giants", description = "The goren and the magnaron are ravaging the element spirits and smelting their essence as one would smelt steel.\n\nCommander, take my totem, travel east to Magnarok. Please, find them, and free them.\n\nDraka and I will make our way to the Ascent of Frostfire. Meet us there if you are successful.", progress = "The ritual was more draining than I could have anticipated.", completion = "You have done well, {class}.\n\nWe will need the aid of these children when the time comes to rescue Exurotus.", objectives = "Rescue Flamrog and Kindler.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32984] = { id = 32984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ascent", description = "I can feel the voice of the Fury at the top of the ascent. Come, let us climb these stairs together.\n\nBe on your guard. The goren of this area are likely to be drawn by the smell of a shaman.\n\nIf we get separated, fall back to the base of the stairs and regroup.", completion = "This is ancient magic, from a time before the orcs. It will not be easy to undo.", objectives = "Bring Drek'Thar to Exurotus, the Spirit of Frostfire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32985] = { id = 32985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fury of Frostfire", description = "The moment I begin the ritual to free Exurotus you can expect Kron to be drawn to us. \n\nIt would normally take an army of seasoned warriors to defeat a magnaron. We have only the three of us.\n\nLook for my fire totem upon the battlefield. I will try to gain what boons I can from Exurotus. Step near the totems and become one with the Fury.\n\nWith these boons, slay Kron! Lok'tar ogar!", progress = "The... Fury... is nearly free!", completion = "With Kron defeated I can finish breaching the magic that holds Exurotus, but I may be too late. So much of the fury has already been expended and drained by the magnaron and goren.\n\nI fear we may have only bought this spirit a peaceful death.", objectives = "Defeat Kron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32989] = { id = 32989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Securing the South", description = "We have an outpost to the southeast that was boxed in by Thunderlord forces as they marched through the canyons to Wor'gol.\n\nI have sent reinforcements to secure the outpost and press east to Grom'gar. We will push the Thunderlords out of our lands completely, and pursue them all the way back to that reeking corpse they call home.\n\nDraka's sister, Lokra, was among the orcs who volunteered to clean up Stonefang Outpost.", completion = "{name}! They told me you'd be heading this way. You are late to the party! We are just cleaning up now.", objectives = "Speak with Lokra at Stonefang Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32990] = { id = 32990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Who Held Fast", description = "The siege has been broken - they underestimated the resilience of Stonefang, and our reinforcement wave from Bladespire caught them completely off-guard.\n\nOnce we finish cleaning up here, we rally anyone who can still fight and prepare to march for Grom'gar.\n\nThe outpost captain, Karg Bloodfury, should have come out to meet us by now. Can you get him out here?\n\nTell him Lokra is waiting. He knows how much I hate to be kept waiting.", progress = "You go ahead - Asha and I will hold here for now.", completion = "You're back! But where is Karg?", objectives = "Speak with Karg Bloodfury in Stonefang Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32991] = { id = 32991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Boneslag", description = "The Thunderlords took prisoners into the Boneslag?\n\nWell what are we waiting for?! We have to go after them!\n\nYou look for the missing villagers - Asha and I will track Karg.", completion = "Thank you for finding the others. Karg and his captor are one step ahead of us, but they're limping.", objectives = "Search the Boneslag for the missing Frostwolf orcs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32992] = { id = 32992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moving Target", description = "Karg's captors are moving east - probably retreating to Grom'gar with their tails between their legs!\n\nThey think they outrun me, but Asha here is the fastest thing on four legs. We'll run them down in the Icewind Drifts.", completion = "<Lokra's gaze remains fixed on her dying frost wolf.>\n\nWe had them... We had them, Asha. You were so fast. So beautiful.\n\nI failed you, Asha. I am sorry.", objectives = "Catch up with Lokra in the Icewind Drifts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32993] = { id = 32993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Strength of Our Bonds", description = "Asha has passed, but we share a bond that cannot be severed by death. Even now, her spirit urges me onward to Grom'gar.\n\nThe Iron Wolf claims our attachments make us weak... that love makes us vulnerable.\n\nHe is wrong.\n\nKarg is my strength, and I his. I will free him from his chains, and together we will show the Thunderlord clan the strength of our bonds.", completion = "Help me out of these chains. We have work to do.", objectives = "Find Karg Bloodfury in Grom'gar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32994] = { id = 32994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enfilade", description = "If we leave now, my clan's final assault on Grom'gar will be a disaster.\n\nThough our warriors are unmatched in melee, the Thunderlords have new ranged weapons - our forces would be decimated as they cross the Icewind Drifts.\n\nBut WE are already here. We can overtake those weapons before they ever fire.\n\nBlackrock orcs help our enemies forge these \"cannons\" in the workshops on the south side. If we use their own tools to sabotage the weapons, we leave Grom'gar wide open to a Frostwolf raid.", progress = "If we leave those cannons intact, my brothers and sisters will die. What more is there to say?", completion = "See how their machines fail them! There is no better weapon than pure orc muscle!", objectives = "Use Blackrock Blasting Powder to destroy 5 Iron Horde Cannons in Grom'gar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32995] = { id = 32995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blood-Caked Scroll" }
