quests[33007] = { id = 33007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proving Grounds" }
quests[33008] = { id = 33008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Vale", description = "Ah, I have been waiting for your arrival, traveler.\n\nI wish we could meet in better times, but alas, I fear the situation in the Vale is quite dire.\n\nBut let us not speak of that now. Go visit Madam Vee Luo at the Shrine of Two Moons.\n\nShe should be able to settle you in.", sourceObjective = "Speak to Madam Vee Luo at the Shrine of Two Moons in the Vale of Eternal Blossoms.", sourceObjectiveStatus = "unverified-source-field" }
quests[33010] = { id = 33010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Iron Wolf", description = "My brother Ga'nar stands beside me.\n\nWor'gol, Stonefang, and your garrison hold strong.\n\nOur clan is united, and the Thunderlord are already on the run. We are ready. The time has come to face this \"Iron Wolf.\"", completion = "Thank you for protecting my family, {name}.", objectives = "Enter the Hunter's Hall in Grom'gar and defeat the Iron Wolf.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33011] = { id = 33011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Frostwolf Veteran's Keepsake" }
quests[33012] = { id = 33012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Task: Stonefang Outpost Fires", objectives = "Pick up snowballs from Snow Mounds and throw them at burning structures in Stonefang Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33013] = { id = 33013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of Fire and Thunder", description = "The Iron Wolf... brought weapons...\n\n<cough>\n\n...weapons of fire and thunder.\n\nOur warriors have never seen such weapons. We were not ready.\n\n<wheeze> We must learn... to overcome...", objectives = "Examine the Siege Munitions and Heavy Plating in The Boneslag.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33014] = { id = 33014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Cindermaw" }
quests[33015] = { id = 33015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunderlord War-Gronn", objectives = "Slay 6 Thunderlord Giantslayers or Thunderlord Gronnstalkers around Kron'mar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33016] = { id = 33016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Frostwolf Supply Cache" }
quests[33017] = { id = 33017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Iron Horde Supply Wagon" }
quests[33018] = { id = 33018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noodle Secrets Long Forgotten", description = "Searching amidst the rubble, you find the fragment of an old sign. Wiping away the dust, you can make out the well-weathered pandaren characters for \"Noodles\" and \"Lin.\"\n\nLooking above, you suspect that the establishment this sign belonged to was situated on the bridge, which now lies in rubble about you. An eatery placed on a bridge sounds very temporary, so its owner would likely live nearby.\n\nPerhaps there is a clue to be found in the village here on the island?", completion = "Well, hello there. I am Lin Chao-Wei.\n\nHave you come here to try my family's famous noodle soup?", objectives = "Search the village, Old Pi'jiu, on the Timeless Isle, for the owner of the old sign fragment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33019] = { id = 33019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "NC S1 Q2", description = "Well hello there. I am Lin, Chao-Wei. Have you come here to try my family's famous noodle soup? I'm afraid you're all out of luck. My father passed away before he could teach me the secret ingredient to his secret ingredient noodle soup. He did mention writing down the recipe for a friend of his that went to the Temple of the Jade Serpent. Perhaps you can find it there?" }
quests[33020] = { id = 33020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Secret of the Secret Ingredient", description = "If you've come here to try my family's famous noodle soup, I'm afraid you're out of luck.\n\nMy father passed away before he could teach me the secret ingredient. He did mention writing down the recipe for a friend of his that studied at the Temple of the Jade Serpent.\n\nPerhaps you can find it there?", completion = "You recognize the name, Lin, on the scroll. A few characters down you see the character for \"Recipe.\"\n\nThis must be it!\n\nYour only worry is that the sha energies that manifested themselves in the tales of the pandaren may have corrupted the scroll as well.\n\nThere is only one way to find out....", objectives = "Defeat the Sha of Doubt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33021] = { id = 33021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets Lost, Forever?", description = "<With the ancient Lin family noodle soup recipe in hand, you decide to set out for the Halfhill Market.>\n\n<If anyone in Pandaria knows how to decipher this scroll, it's Sungshin Ironpaw.>", completion = "Hello, {name}. What is it you have there?", objectives = "Speak with Sungshin Ironpaw at the Halfhill Market in the Valley of the Four Winds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33022] = { id = 33022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catch and Carry", description = "Oh my! Grandpa used to tell me stories of the famous Lin family noodle shop.\n\nIt is sad that the scroll has been warped, but I think we can work together to solve the riddle!\n\nTo start, we're going to need lots of grain to make noodles.\n\nHead down to the granary and catch some grain with this sack. After you've caught some, drop it off at the wagon I've placed at the granary.", completion = "Excellent work, {name}! With all this grain I think we're ready to start.\n\nFor now I think you should try making noodle soup. Try using this recipe I've written down for you. It'll make for excellent practice.", objectives = "Use the Grain Catching Sack to catch 20 Sacks of Grain being thrown down by the Granary Vandals at the Imperial Granary.\n\nYou will drop all your carried grain if you mount or get hurt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33023] = { id = 33023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "NC S1 Q6" }
quests[33024] = { id = 33024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Is That A Real Measurement?", description = "Well done, {name}. I can see you're ready to continue exploring the mysteries of Lin's secret ingredient soup.\n\nFrom what I can tell, Lin used Stormstout brew for his soup broth.\n\nI think the next steps for you are to create a Noodle Cart of your own and to head to the Stormstout Brewery to collect some sloshes of brew.", progress = "I'm glad it's you and not me. I'm not much of a drinker, myself.", completion = "Well done, {name}. With this we can make a truly unique soup broth.\n\nI've managed to get some updated schematics for your noodle cart. With this broth, you're definitely going to want to upgrade your operation.\n\nNext up: finding the secret ingredient of the Lin secret ingredient noodle soup!", objectives = "Create a Noodle Cart Kit and collect 20 Sloshes of Brew from slain alementals in the Stormstout Brewery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33025] = { id = 33025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "NC S2 Q2" }
quests[33026] = { id = 33026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "These Aren't Your Fatty Goatsteaks", description = "I'm so excited, {name}. We've nearly mastered all the ingredients for noodle soup!\n\nWe have plenty of vegetables and spices here, but the Lin family had access to exotic meats not seen in Pandaria for some time. We need some nice, fatty meats.\n\nGrandpa used to tell me of ancient turtles living off the shores of the Timeless Isle. Something that lives that long has to have some nice fatty meat on its bones.\n\nCreate a deluxe noodle cart and gather some fatty turtle steaks and we'll continue.", progress = "I can just taste the soup now!", completion = "Ooh, these will do nicely, {name}.\n\nNow for the final step: the Lin secret ingredient soup's secret ingredient.\n\nThat's a mouthful!", objectives = "Create a Deluxe Noodle Cart Kit and collect 50 Fatty Turtle Steaks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33027] = { id = 33027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Secret Ingredient Is...", description = "The best way to go about doing this is through hands-on experience.\n\nI've arranged for merchants, scholars, and farmers from all over Pandaria to come for a taste test of your soups. We'll get the best results if you can match them to the soups they prefer.\n\nIt's time to find the secret ingredient!", progress = "{name}, we need to find the secret ingredient if we're to ever master the Lin family's noodle soup!", completion = "Well done, {name}. All those people came by to taste your noodle soup and YOU made them so happy!\n\nDon't you see? The secret ingredient is in you!\n\nNow go out there and make the world happy with this latest noodle cart!", objectives = "Queue for and complete the Finding the Secret Ingredient scenario.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33028] = { id = 33028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Karabor!", description = "Draenor will not be a friendly place for someone like you. There are far too many orcs here, and I know your kind has a history with the orcs.\n\nNo, if you're looking for a friendly face here on Draenor, you'll need to find the draenei.\n\nHop on my back. I will take you to the draenei temple of Karabor.", objectives = "Speak with Chronalis, then fly into Karabor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33035] = { id = 33035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Pale Capture" }
