quests[33056] = { id = 33056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Hygrocybe" }
quests[33057] = { id = 33057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Rotbelcher" }
quests[33058] = { id = 33058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Collect Karabor Axes", description = "Some of our bravest champions have fallen today.\n\nTo make matters worse the Iron Horde has started using our own weapons against us. \n\nThe idea of my people being slain with the weapons forged by our ancestors makes me sick.\n\n{name}, could you please retrieve these weapons and bring them back to me?", objectives = "Collect 5 Karabor Weapons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33059] = { id = 33059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of Karabor", description = "Threads of the future weave together, winding and unwinding, creating tapestries that change in form and color from one moment to the next.\n\nI must have clarity. I must focus on the ONE strand that will become reality.\n\nWhen you are ready to share in my vision, drink the elixir.\n\nWhen the vision begins, be on your guard. The events of the vision are as deadly as anything we experience in this reality.", progress = "<The Prophet is deep in thought. He looks troubled.>", completion = "I have seen enough. Ner'zhul must be stopped.", objectives = "Drink the Clarity Elixir and witness the fate of Karabor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33060] = { id = 33060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Put down Poisonfiend.", description = "Zugunk Poisonfiend is to blame for this madness.\n\nHe has contaminated this temple and it is time for his reign of terror to end.", objectives = "Kill Zugunk Poisonfiend", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33061] = { id = 33061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Amaukwa" }
quests[33062] = { id = 33062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catching His Eye", description = "For what must be done, I need someone I can trust. You're one of those few.\n\nThe woods and the orc village, Gul'var, are protected from my scrying magic. We need to pierce that veil. I think I know a way.\n\nThere's a fel presence within the woods. A demonic watcher is there, hidden in a cave from which it casts its all-seeing gaze.\n\nI would like for you and the warden to capture it.", completion = "As soon as we have enough blessed water from the priestess's moonwell, we'll break the demon's will and use it as a proxy to see into Gul'var.\n\nThat way, they won't know it's us scrying upon them.\n\nBut first, we need to weaken their shrouding magic.", objectives = "Capture the All-Seeing Eye.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33064] = { id = 33064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Shadowmoon Cultist Ritual" }
quests[33065] = { id = 33065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Mooncrush" }
quests[33066] = { id = 33066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soul Shards of Summoning", description = "It's good to know what Teron'gor and Cho'gall are up to. It's more important that we stop Gul'dan.\n\nSome of his disciples can summon minor demons. To do this, these lesser warlocks must use a soul shard. The foul crystal creates a connection to the Twisting Nether, pulling a demon through against its will.\n\nGul'dan's as much demon as he is orc. If we can gather some of the more potent shards, we can combine them into something that just might capture him.", progress = "Do you have the shards, {name}?", completion = "Now all that's left to do is to fashion them together into something strong enough to ensnare Gul'dan.\n\nLuckily, we can do that right here.", objectives = "Collect Kurgoth's Shard, Grogal's Shard, and Hagra's Shard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33067] = { id = 33067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Task: Warsong Riot", description = "The Warsong Ragemongers are attacking the temple!", objectives = "Kill Warsong Ragemongers near the Temple of Katabor in Shadowmoon Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33068] = { id = 33068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Task: Retrieve Thunderlord Armbands" }
quests[33069] = { id = 33069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSEME" }
quests[33070] = { id = 33070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Think of the Children!", description = "When the Shadowmoon attacked Arbor Glen, everything was thrown into chaos.\n\nMany of us escaped, but there are still three children missing.\n\nI believe they are still back in the village.\n\nPlease save them!", completion = "I am glad to hear that the children are safe. They will remember your heroic deeds for their entire lives.", objectives = "Save Rastaak, Ariaana, and Hakaam.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33071] = { id = 33071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call of War", description = "If you are reading this letter, it likely means that I am dead. Please deliver this to my son, Faran, at Teluuna Observatory.\n\n\nDearest Faran and Elsa,\n\nI have fallen in the line of duty while defending the Temple of Karabor.\n\nPlease know that I love you both with all of my heart. My spirit will watch over you for the rest of your days. Be strong, love one another, and live this life to the best of your ability.\n\nI am so proud of you both.\n\nLove,\n\nYour Mother", objectives = "Deliver Kaati's Letter to Faran at Teluuna Observatory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33072] = { id = 33072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into Twilight", description = "The safety of my people is of the utmost priority.\n\nIt is likely that Ner'zhul has taken the prisoners to Shaz'gul, his stronghold to the southwest.\n\nI do not wish to use aggression against him, but he may force my hand.\n\nMeet me at Twilight Glade, {name}. Then, we shall try our best to recover the prisoners.", completion = "Thank you for coming, {name}. There is much to be done.", objectives = "Speak to Prophet Velen at Twilight Glade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33074] = { id = 33074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Memory of Fire", description = "<The obsidian chip is hot to the touch, but strangely, can be held with no fear of being burned.>\n\nOn its surface is etched a picture - a rectangular stone with a hole cut through the middle, surrounded by a ring of flames.\n\nThere is just such a stone in the fields to the north.", objectives = "Use the Dancing Ember at the ring of fire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33075] = { id = 33075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hero's Welcome", description = "Prophet Velen has asked me to show you around Shadowmoon Valley.\n\nWe will go first to Embaari Village, where my sister Samaara is waiting for us. I have not seen her since the Iron Horde took me to Tanaan.\n\nThe village is just one of many trading villages between the Temple of Karabor and Shattrath.\n\nFollow the road east and make your way to Embaari Village. I will accompany you, my friend.", completion = "Thank you, stranger! The Prophet spoke of new allies arriving on our shores.\n\nI hear it is thanks to you that my sister is safe.\n\nI owe you a great debt, friend.", objectives = "Speak to Samaara at Embaari Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33076] = { id = 33076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Clarity Elixir", description = "I see a thousand glimpses of the future, swimming in a chaotic blur.\n\nIt is possible to focus my energies to see the true eventuality - the future most likely to come to pass.\n\nI will need an oracle stone to focus my power, and a special elixir to still my mind.\n\nTo make the elixir, I will need the following ingredients: wing dust from Swamplighters along the river, fresh hearts from a monstrously-sized hydra, and a rare star lily.\n\nMeet me at Moonwillow Peak when this task is done.", progress = "Yes?", completion = "My trust in you is well placed, young {class}.\n\nThis task would have been troublesome for many of my students, and yet you finished it with ease.", objectives = "Collect 6 Swamplighter Dust, 3 Engorged Hearts, and 1 Starflower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33077] = { id = 33077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Grandmother's Remedy", description = "Oh my, such a vigorous young <lad/lass>! Such a spring in your step, and such a sparkle in your eye!\n\nWhen you get to my age, it's all aches and pains.\n\nLuckily, I have a recipe for an unguent that would soothe my joints. I just need the ooze from the skin of belly toads in the swamp.\n\nWould you be a dear and help an old woman out?", progress = "It's all downhill from here, dearie.", completion = "Oh thank you child, thank you, thank you.\n\nThe nights in the swamp are cold. It means a lot to this old woman to have some comfort from her aching bones.", objectives = "Collect 6 Vials of Toad Juice.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33078] = { id = 33078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark that Blinds Us", description = "After years of research, there is still so much I do not understand about the Shadowmoon.\n\nTo the southwest are stone monuments detailing the orcs' history.\n\nI'm not able to get close enough to examine the stones, but perhaps you can.\n\nIf you could take a chalk rubbing of the words written on those stones, and I will reward you handsomely.", progress = "What did you find?", completion = "Oh my, I see, I see! These writings will give me much insight into the Shadowmoon clan's culture.\n\nThank you, {name}.", objectives = "Take chalk rubbings of the northern, eastern, western, and southern Tribal Stones in the Whispering Fields.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33079] = { id = 33079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Demons Among Us - Alliance", description = "Now that we have the cloth and leather, we can craft a fitting disguise for our infiltration mission.\n\nGo speak to Ginni Gingerlips. She has proven herself quite capable in the realm of... errr... garment design.", objectives = "Speak to Ginni Gingerlips to craft a Shadowmoon orc disguise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33080] = { id = 33080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Going Undercover", description = "Yrel leads my rangers on a search for the prisoners at the Shadowmoon village.\n\nTheir work is extremely dangerous, so I need you to carry out a contingency mission.\n\nSylene has mastered an illusion spell which will allow you to infiltrate Shaz'gul safely. Speak to her to disguise yourself.\n\nThen, plant explosives at the quartermaster's depot, the main lodge, and the ritual altar.\n\nIn case anything goes wrong, set them off to create a distraction.", completion = "You made it, {name}! Boy, am I glad to see you.", objectives = "Speak to Sylene at Twilight Glade to gain an orc illusion, then plant explosives at key locations in Shaz'gul.\n\nIf you lose your disguise, use Sylene's Amulet of Illusion to regain an orc appearance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33081] = { id = 33081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escape From Shaz'gul", description = "I've failed, {name}...\n\nMy squadron was caught by a wandering patrol. We fought fiercely, but the alarm had been raised. The rangari forced me into hiding before surrendering themselves to the enemy.\n\nThey were under MY command, and they gave their lives... for what? I... I'm not sure what to do, {name}.\n\nWe need to get out of here, but how?", completion = "I could never have done it without you, {name}. Your words unlocked something within me which I have not felt before.\n\nCall it what you wish - resolve, conviction, faith. I will not soon forget this, {class}.", objectives = "Help Yrel escape from Shaz'gul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33082] = { id = 33082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancestor's Memory", description = "I believe that you should know the price of the lives you take.\n\nSo before I will help you find Ner'zhul, you must understand why he joined the Iron Horde.\n\nIn a cave beneath this village is an artifact that we call the Ancestral Totem. On it is carved the names of every Shadowmoon clan member since its founding.\n\nThe opening of the cave lies directly south. I will meet you there.", progress = "You must understand a man's life before taking it.", completion = "We will find new traditions. My people will become something... new.", objectives = "Find the Ancestor's Totem in the cave beneath Exile's Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33083] = { id = 33083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On the Offensive", description = "We cannot enter these gates, but you can, {class}.\n\nYour mission is critical, and the Shadowmoon will kill you on sight. Do not hesitate to return the favor.", completion = "The Shadowmoon are not simple opponents. Your fighting skill is truly comparable to none.", objectives = "Kill 15 Shadowmoon Darkcasters or Shadowmoon Voidclaws.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33084] = { id = 33084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Big Haul", description = "Ey commander, fancy runnin' inta ya out here!\n\nTha garrison's got plenty a hungry mouths ta feed, with more folks comin' by every day.\n\nWe're really gonna need a big haul o' meat ta keep everyone happy.\n\nWouldya care ta lend us a hand? It'll be faster work with an extra pair a hands.", progress = "Have ya seen tha size a these beasts?", completion = "Brilliant, just brilliant! Ay've never seen such a haul in my entire life!\n\nGet tha wagons ready. We're eatin' well tonight!", objectives = "Collect 1000 Raw Elekk Steaks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33085] = { id = 33085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallen From the Stars", description = "The final ingredient is a rare flower that grows only in the heart of the Nightmarsh.\n\nThis flower feeds only on starlight, and dies when it falls under shadow.\n\nIf you can find such a flower, bring it to me. Only its essence will help me gain the clarity I need.", objectives = "Collect 1 Pristine Starflower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33086] = { id = 33086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: The Root of Darkness - Stone 1" }
quests[33087] = { id = 33087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet Me Back at the Inn", description = "I'm certain you're eager to test out your new cloak. Let's put it to use.\n\nMeet me back inside the inn! A new development has come to my attention that we'll want to take advantage of.", completion = "Are you ready for your next adventure?", objectives = "Meet Wrathion upstairs at the Tavern in the Mists in the Veiled Stair.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33088] = { id = 33088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Timeless Discovery", description = "Pandaria. Just when I think I've gotten its mysteries figured out, I discover something new.\n\nIt's called \"The Timeless Isle.\" Once hidden in the mists, it appears and disappears seemingly of its own will. I've heard that time has no meaning there, that the sun neither rises nor sets.\n\nWe can take advantage of this anomaly, {name}! If I could time-lock your cloak, the power it could contain would be... immense.\n\nOur path is clear. Fly southeast of the Jade Forest and meet me at the Timeless Isle!", completion = "You're here! How long have I been waiting for you?\n\n<Wrathion appears momentarily confused.>\n\nI feel like I just arrived... but maybe I've been here for weeks... This island plays with one's head.\n\nKairoz has been trying to explain it to me, but sometimes I think bronze dragons speak in riddles.", objectives = "Travel to the Timeless Isle southeast of the Jade Forest and speak with Wrathion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33089] = { id = 33089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Proving Grounds - Damage Bronze" }
quests[33090] = { id = 33090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Proving Grounds - Damage Silver" }
