quests[33097] = { id = 33097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Proving Grounds - Healer Gold" }
quests[33098] = { id = 33098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Timeless Isle", description = "There is a currency minted only on this island - \"timeless coins.\" They are immune to the island's temporal distortions... I would like to figure out why.\n\nGather some for me! Venture into the jungles of this forgotten paradise. Destroy the mysterious foes who lurk in this timeless place, discover hidden caches of treasure, and explore forgotten treasure hoards - whatever it takes. I will be waiting!", progress = "<Wrathion tents his fingers together.>\n\nMy coins...?", completion = "Wonderful, these are exactly what I need.\n\n<Wrathion holds one of the coins up, admiring it in the glow of the unmoving sun.>\n\nI will deconstruct their mysterious power, and use their timelessness to enhance your cloak. You will be most pleased with the result.", objectives = "Collect 5000 Timeless Coins from creatures and events on the Timeless Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33100] = { id = 33100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Emperor's Way", description = "Recently, the August Celestials of Pandaria presented you with a challenge - and you triumphed.\n\nBut can you defeat them in combat? They are testing the mettle of all of Pandaria's heroes.\n\nThis challenge is not impossible, but you'll need to follow the advice of the last Pandaren Emperor and tackle it with unwavering inner strength. You'll also need a small army, so find a group of people you trust.\n\nDefeat the four celestials here in the Celestial Court, and our journey is almost complete...", completion = "An impressive display of martial skill, {class}! You have truly walked the path of the emperor, and demonstrated the very traits pandaren value most.", objectives = "Defeat Yu'lon, Chi-Ji, Xuen and Niuzao, the four August Celestials of Pandaria.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33104] = { id = 33104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Pandaren Legend", description = "I have learned so much in this timeless place, friend. Between the wisdom of the celestials and the curious power of these timeless artifacts, I know now how to safely augment your cloak with my own considerable power.\n\nI need a sacred place to complete my final incantations. Quickly! Meet me in the Vale of Eternal Blossoms, within the Seat of Knowledge above the Mogu'shan Palace.\n\nToday, your legend begins!", completion = "Step forward, my champion.\n\nThis is your hour.", objectives = "Meet Wrathion within the Seat of Knowledge in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33105] = { id = 33105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Judgment of the Black Prince", description = "Now. To the final stage of my plan. Time to fulfil your grand purpose.\n\nUsing your newfound powers, it is time to bring this war to its conclusion. Destroy Garrosh Hellscream. Your people demand it, and future generations will sing your praises as the harbinger for the glorious new world we shall build together.\n\nI have no reward to offer you. I have already done everything in my power to ensure that you succeed. You are on your own.\n\nEnd Hellscream's reign.", completion = "<Wrathion is FURIOUS. News of Hellscream's defeat and King Wrynn's gesture of peace must've already reached the black dragon's ears.>", objectives = "Complete the Siege of Orgrimmar and defeat Garrosh Hellscream.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33107] = { id = 33107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bad Feeling, Worse Result", description = "<As you open the scroll, you realize your worst fears have come true: the sha energies have corrupted the Lin recipe.>\n\n<Your only choice is to defeat the released energies in the hope that the scroll can be saved.>", objectives = "Defeat the Ghost of Lin Da-Gu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33108] = { id = 33108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Task: Poisionous bunnies", description = "A large number the bunnies in the area have been infected with a toxic poison.\n\nIt might seem cruel but burning the bodies of the bunnies is the only way to ensure the infection will not spread.", objectives = "Burn 5 poisonous bunnies", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33109] = { id = 33109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[33110] = { id = 33110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Usurper", description = "This fragment of the heart of Y'shaarj lies completely inert. You should bring it to the remnants of the Golden Lotus as proof that Garrosh has been defeated.", objectives = "Claim your reward for deposing Garrosh Hellscream as Warchief of the Horde.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33111] = { id = 33111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bounty: Twisted Ancient", description = "The ancients of the Cursed Woods have been corrupted by demonic magic. Since they need to be destroyed, we might as well make use of their resources. Waste not, want not.\n\nBeware: these woodland behemoths are no easy targets. Gather trusted friends before you engage these twisted ancients.\n\n-- Baros Alexston", progress = "Have you read the bounty I posted concerning the twisted ancients in the Cursed Woods?", completion = "Unfortunate that the ancient guardians of the woods fell to such corruption.\n\nAt least now, its long nightmare has ended. Not to mention its sacrifice is our gain.", objectives = "Collect Corrupted Lumber from a Twisted Ancient.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33112] = { id = 33112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ominous Portents", description = "Now that Priestess Moonfang has created the blessed water, it is time to deal with the demon.\n\nTake the water and the scripture of Elune.\n\nThrough the power of each, you will compel the demon to show us what the orcs are up to at Gul'var.", progress = "The demon must be put to the test if we're to find out what's happening at Gul'var.", completion = "Gul'dan is there! We must move quickly to capture him.", objectives = "Compel the All-Seeing Eye.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33113] = { id = 33113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowmoonwell", description = "The archmage has asked me to prepare this moonwell. Once it is completed, I'll be able to sanctify its water for use against the demon.\n\nOnly one thing remains.\n\nA piece of one of Draenor's moons has fallen into a nearby pool on the far side of the woods. Such a thing is perfect for use in the dedication of the moonwell to Elune.\n\nWill you bring it back for me, {name}?", progress = "With that chunk of fallen rock, I'll be able to complete the dedication of the moonwell.", completion = "Thank you, {name}. The White Lady will be pleased.\n\nNow, I shall go about the business of preparing the moonwell water for use in the archmage's plan.\n\nBut first, I wonder if you'd be willing to help me again. The warden brought back very disturbing stories about the creatures in the woods.", objectives = "Collect a Chunk of Lunar Rock.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33114] = { id = 33114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forging the Soul Trap", description = "The fiery heart of Krosnis is in the forge. We have the soul shards.\n\nNow all that is left to do is to stoke the fires and combine all of these foul components into a trap for Gul'dan.", progress = "With the soul shards combined, we will trap Gul'dan and put an end to the Shadow Council on Draenor.", completion = "You've forged the soul trap. There's no time to waste, {name}.\n\nWe must capture Gul'dan.", objectives = "Forge Gul'dan's Soul Trap.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33115] = { id = 33115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shrouding Stones", description = "Long ago, the shaman of the Shadowmoon clan erected three stones in the woods. There, they performed their sacred rituals, blessing the beasts and the trees.\n\nNow, someone has placed a fel magic upon those stones. This corruption is what shrouds the village of Gul'var.\n\nBefore we can use the captured demon to safely peer into the Shadow Council's village, we must bring down those stones.", completion = "Now that the veil has been lifted from the woods, we can make use of the demon.\n\nWe will convince it to turn its eye upon Gul'var and show us what the Shadow Council is planning.", objectives = "Destroy the Central, Northern, and Southern Shrouding Stones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33116] = { id = 33116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Catch a Shadow", description = "Gul'dan is on the Shadow Rise just up the hill to the west. But, you must hurry, {name}. We know that he's about to leave for Talador and Frostfire Ridge.\n\nThe use of the soul trap is straightforward. Simply point and shoot to ensnare Gul'dan. The crystal will take care of the rest.\n\nI'll see you back at Starfall Outpost when you have him.\n\nGood luck.", completion = "Unfortunate, but not surprising. At least we were able to defeat one of the inner council members.\n\nAll is not lost, {name}. We know what the Shadow Council is up to and where they're heading.\n\nWe'll regroup in Talador. Together, we'll put an end to Teron'gor and his plans for Auchindoun.\n\nDid you hear that?", objectives = "Use Gul'dan's Soul Trap on Gul'dan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33117] = { id = 33117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[33118] = { id = 33118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[33119] = { id = 33119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slavery and Strife", description = "We have their citadel, but they still have some of my people enslaved at the Sootstained Mines.\n\nWe have no one to spare, but you seem more than capable of handling a few ogres on your own.\n\nI ask that you release any enslaved Frostwolves you find there, and keep an eye out for Mulverick.", progress = "Free my people and then we can talk!", completion = "Who are you, outsider? I saw you freeing some of my kin...", objectives = "Free 5 Frostwolf Slaves from the Sootstained Mining Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33120] = { id = 33120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Curse Upon the Woods", description = "Cordana tells me that the creatures of the woods are cursed by the same fel energies keeping Khadgar from scrying into the orc village.\n\nThis will not do.\n\nIf we were on Azeroth, I could find a cure in a reasonable timeframe. However, we are not, nor do we have the luxury of time.\n\nBetter to put a swift end to their suffering rather than allow these poor creatures to linger with demonic energy.", completion = "Grim business. I wish that it could have gone differently.\n\nThank you for your dedication, {name}. Be comforted in the fact that Elune understands.", objectives = "Kill 10 fel-cursed creatures in the Cursed Woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33123] = { id = 33123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Celestial Tournament", description = "The Timeless Isle is home to a special tournament created to test the leadership of its participants.  Those who prove their worth are granted an opportunity to befriend an embodiment of virtue - the progeny of the Celestials themselves.\n\nEach time you win the tournament, I will honor you with a single ceremonial coin.  When you have enough coins, speak with me again to further discuss your reward.", objectives = "Win the Celestial Tournament. Master Li can enter you into the tournament.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33124] = { id = 33124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fishing with Fin - Tracking Quest" }
quests[33125] = { id = 33125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Proper Parting", description = "The ogres outnumbered us, *cough* but we made them pay for their deeds in blood.\n\nEven so, I was forced to abandon my fallen brothers and sisters on the battlefield. They deserve better than to have their corpses despoiled by the ogre filth.\n\nHere, take this torch *cough* and do what I could not: burn the corpses of my fallen brothers and sisters to the west.", progress = "Did you give the others a proper burial?", completion = "You bring honor to the clan by giving my family a proper burial, {name}.", objectives = "Burn the corpses of dead Frostwolf Outriders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33126] = { id = 33126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Task: Clear Out Grimfrost Hill.", description = "Kill Grimfrost Ogres", objectives = "Kill ogres on Grimfrost Hill", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33129] = { id = 33129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Task: Poisionous bunnies", description = "A large number the bunnies in the area have been infected with a toxic poison.\n\nIt might seem cruel but burning the bodies of the bunnies is the only way to ensure the infection will not spread.", objectives = "Burn 5 poisonous bunnies", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
