quests[33131] = { id = 33131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Put down Poisonfiend.", description = "Zugunk Poisonfiend is to blame for this madness.\n\nHe has contaminated this temple and it is time for his reign of terror to end.", objectives = "Kill Zugunk Poisonfiend", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33132] = { id = 33132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gut Guttra", description = "Snowpaw was able to help me to here so that I might strike against their leader, Guttra, but I have lost too much blood. My time is near.\n\nDo you have the strength to help me avenge my fallen brothers and sisters and kill Guttra Wolfchew?\n\nThe monster resides in the tallest tower of Grimfrost.", progress = "Did you kill Guttra Wolfchew?", completion = "Wolfchew is defeated? *cough* Glorious.", objectives = "Slay Guttra Wolfchew.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33133] = { id = 33133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warforged Seals", description = "Greetings, {name}. I am privileged to offer you an excellent opportunity. Through the centuries, we've honed a method by which the very laws of chance themselves can be bent. With a Warforged Seal, valuable artifacts will find their way into your hands more frequently as you pursue Garrosh.", progress = "May these charms bring you great luck, {name}.", completion = "May the stars smile upon you, {name}.", objectives = "Collect 50 Lesser Charms of Good Fortune.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33134] = { id = 33134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warforged Seals", description = "Greetings, {name}. I am privileged to offer you an excellent opportunity. Through the centuries, we've honed a method by which the very laws of chance themselves can be bent. With a Warforged Seal, valuable artifacts will find their way into your hands more frequently as you pursue Garrosh and his forces.", progress = "May these charms bring you great luck, {name}.", completion = "May the stars smile upon you, {name}.", objectives = "Collect 50 Lesser Charms of Good Fortune.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33135] = { id = 33135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleaning Up Gul'var", description = "Just because we need to focus on Gul'dan doesn't mean we're not going to take down the Shadow Council in the process.\n\nThis village is filthy with Shadow Council villains. Let's do something about them.", completion = "Every world is better off without those demon-loving scum.", objectives = "Kill 20 Shadow Council orcs at Gul'var.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
